import{WOOTZ_DATA}from"./wootz-steel-data.js";function initTheme(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const t=document.body.classList.contains("light-theme");localStorage.setItem("theme",t?"light":"dark"),e.textContent=t?"🌙":"☀️"})}function initNavbar(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&e.addEventListener("click",()=>{const n="true"===e.getAttribute("aria-expanded");e.setAttribute("aria-expanded",!n),t.classList.toggle("active")})}function renderStats(){const e=document.getElementById("stats-grid");e&&WOOTZ_DATA.stats&&(e.innerHTML=WOOTZ_DATA.stats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-value">${e.value}</div>\n            <div class="stat-label">${e.label}</div>\n        </div>\n    `).join(""))}function renderHeroImage(){const e=document.getElementById("hero-image-wrap");e&&WOOTZ_DATA.heroImage&&(e.innerHTML=`\n        <img src="${WOOTZ_DATA.heroImage.url}" alt="${WOOTZ_DATA.heroImage.caption}" loading="lazy" />\n        <figcaption>${WOOTZ_DATA.heroImage.caption}</figcaption>\n    `)}function renderHistory(){const e=document.getElementById("history-title"),t=document.getElementById("history-content");e&&(e.textContent=WOOTZ_DATA.history.title),t&&(t.textContent=WOOTZ_DATA.history.content)}function renderProcess(){const e=document.getElementById("process-title"),t=document.getElementById("process-content"),n=document.getElementById("process-diagram");e&&(e.textContent=WOOTZ_DATA.productionProcess.title),t&&(t.textContent=WOOTZ_DATA.productionProcess.content),n&&WOOTZ_DATA.productionProcess.steps&&(n.innerHTML=WOOTZ_DATA.productionProcess.steps.map((e,t,n)=>`\n            <div class="process-step">\n                <div class="step-number">${e.step}</div>\n                <div class="step-body">\n                    <h4>${e.title}</h4>\n                    <p>${e.detail}</p>\n                </div>\n            </div>\n            ${t<n.length-1?'<div class="step-connector" aria-hidden="true"></div>':""}\n        `).join(""));const o=document.getElementById("process-image-wrap");o&&WOOTZ_DATA.processImage&&(o.innerHTML=`\n            <img src="${WOOTZ_DATA.processImage.url}" alt="${WOOTZ_DATA.processImage.caption}" loading="lazy" />\n            <figcaption>${WOOTZ_DATA.processImage.caption}</figcaption>\n        `)}function renderBeforeAfter(){const e=document.getElementById("before-after-title"),t=document.getElementById("before-title"),n=document.getElementById("after-title"),o=document.getElementById("before-points"),r=document.getElementById("after-points");e&&(e.textContent=WOOTZ_DATA.beforeAfter.title),t&&(t.textContent=WOOTZ_DATA.beforeAfter.before.title),n&&(n.textContent=WOOTZ_DATA.beforeAfter.after.title),o&&(o.innerHTML=WOOTZ_DATA.beforeAfter.before.points.map(e=>`<li>${e}</li>`).join("")),r&&(r.innerHTML=WOOTZ_DATA.beforeAfter.after.points.map(e=>`<li>${e}</li>`).join(""))}function renderModernApplications(){const e=document.getElementById("modern-title"),t=document.getElementById("modern-content");e&&(e.textContent=WOOTZ_DATA.modernApplications.title),t&&(t.textContent=WOOTZ_DATA.modernApplications.content)}function renderGallery(){const e=document.getElementById("gallery-grid");e&&WOOTZ_DATA.gallery&&(e.innerHTML=WOOTZ_DATA.gallery.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.title}" loading="lazy" />\n            <div class="gallery-info">\n                <h4>${e.title}</h4>\n                <p>${e.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&WOOTZ_DATA.references&&(e.innerHTML=WOOTZ_DATA.references.map(e=>`\n        <a class="reference-card" href="${e.url}" target="_blank" rel="noopener noreferrer">\n            <h4>${e.title}</h4>\n            <span class="reference-source">${e.source}</span>\n        </a>\n    `).join(""))}function renderFacts(){const e=document.getElementById("facts-grid");e&&WOOTZ_DATA.facts&&(e.innerHTML=WOOTZ_DATA.facts.map(e=>`<div class="trivia-box">💡 ${e}</div>`).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderHeroImage(),renderHistory(),renderProcess(),renderBeforeAfter(),renderModernApplications(),renderGallery(),renderReferences(),renderFacts()});